1	// BtTransfer.js —— 蓝牙动态资料集接收器（v1.16.46 主人需求）
2	// ─────────────────────────────────────────────────────────────────
3	// 【触发逻辑】应用级全局生效：app.ux onCreate 调 initBtReceiver() 挂 interconnect
4	// 监听，任何界面收到传输都会触发（不是特定页面触发）。
5	//
6	// 【传输协议】（手机 App / ble_tools → 手环 interconnect onmessage，JSON 文本帧）：
7	//   {t:'ds-begin', ds:'<集目录名>', name:'<显示名>', total:<文件数>}
8	//   {t:'ds-chunk', ds, f:'<文件名>', i:<分片号>, last:0|1, data:'<文本片段>'}   // 大文件分片拼装
9	//   {t:'ds-end',   ds}                                                        // 全部就绪 → 触发加载
10	// 引擎所需完整文件集：meta.txt + map_N.txt + detail_N.txt + block_0.txt（见 docs/资料拆分指南.md）。
11	//
12	// 【落盘位置】internal://files/datasets/<ds>/ —— @system.file 沙箱，运行时可写可读；
13	// /common/ 是 rpk 打包只读资源目录，运行时不可写，所以蓝牙集必须落沙箱。
14	// 引擎按 basePath 读文件，沙箱 URI 直接可用（DatasetManager ds.baseUri 支持）。
15	//
16	// 【加载触发】ds-end 收齐 → registerDynamicDataset 注册（全局生效，搜索/详情立即可达）
17	// → router.replace('/pages/loading?source=bt&ds=<ds>') → loading 页【只】对该集
18	// 建缓存（_lazyInit + _ensureMap + _ensureChunk），不跑历史集 init、不跑全量预热。
19	'use strict'
20	
21	var receiving = null // { ds, name, total, files: {fname: {chunks:{i:data}, got, last}} }
22	var registered = false
23	
24	function _log(msg, level) {
25	  console.log('[BT-DS] ' + msg)
26	  try { if (typeof global !== 'undefined' && global.addRuntimeLog) global.addRuntimeLog('[蓝牙资料] ' + msg, level || 'info') } catch (e) {}
27	}
28	
29	function baseDir(ds) {
30	  return 'internal://files/datasets/' + ds + '/'
31	}
32	
33	// 单文件落盘（分片按序拼装后一次性 writeText）
34	function flushFile(ds, fname, parts) {
35	  return new Promise(function(resolve, reject) {
36	    try {
37	      var file = require('@system.file')
38	      var dir = baseDir(ds)
39	      file.mkdir({ uri: dir, recursive: true, success: function() {
40	        var body = ''
41	        var i = 0
42	        while (parts[i] !== undefined) { body += parts[i]; i++ }
43	        file.writeText({
44	          uri: dir + fname,
45	          text: body,
46	          success: function() { resolve() },
47	          fail: function(err, code) { reject(new Error('writeText fail code=' + code)) }
48	        })
49	      }, fail: function(err, code) { reject(new Error('mkdir fail code=' + code)) } })
50	    } catch (e) { reject(e) }
51	  })
52	}
53	
54	// 处理一条 interconnect 消息（JSON 帧，见头部协议）
55	// ⚠️ 消息形态双兼容（审查修复）：官方互联层可能以 {data:'<json>'} 包装投递
56	//（AssistantEngine 即按 data.data 解析），也可能直接投递裸字符串/对象——
57	// 两种形态都兜住，真机联调无需再改。
58	function handleMessage(data) {
59	  var payload = data
60	  if (data && typeof data === 'object' && typeof data.data === 'string') payload = data.data
61	  var msg
62	  try { msg = typeof payload === 'string' ? JSON.parse(payload) : payload } catch (e) { return }
63	  if (!msg || !msg.t) return
64	
65	  if (msg.t === 'ds-begin') {
66	    receiving = { ds: String(msg.ds || ''), name: String(msg.name || msg.ds || ''), total: msg.total || 0, files: {} }
67	    _log('开始接收资料集: ' + receiving.ds + '（' + receiving.total + ' 个文件）')
68	  } else if (msg.t === 'ds-chunk' && receiving && receiving.ds === String(msg.ds || '')) {
69	    var fname = String(msg.f || '')
70	    if (!fname) return
71	    var rec = receiving.files[fname] || (receiving.files[fname] = { chunks: {}, got: 0, last: false })
72	    var idx = msg.i || 0
73	    if (rec.chunks[idx] === undefined) { rec.chunks[idx] = String(msg.data || ''); rec.got++ }
74	    if (msg.last) rec.last = true
75	  } else if (msg.t === 'ds-file' && receiving && receiving.ds === String(msg.ds || '')) {
76	    // 单帧整文件（小文件可不切片）。空文件名防护（审查修复）：空名会让后续
77	    // flushFile 对目录本身 writeText → 整批落盘失败
78	    var fname2 = String(msg.f || '')
79	    if (!fname2) return
80	    receiving.files[fname2] = { chunks: { 0: String(msg.data || '') }, got: 1, last: true }
81	  } else if (msg.t === 'ds-end' && receiving && receiving.ds === String(msg.ds || '')) {
82	    var ds = receiving.ds
83	    var name = receiving.name
84	    var files = receiving.files
85	    receiving = null
86	    _log('接收完成: ' + ds + '，共 ' + Object.keys(files).length + ' 个文件，落盘中…')
87	    var chain = Promise.resolve()
88	    Object.keys(files).forEach(function(fn) {
89	      chain = chain.then(function() { return flushFile(ds, fn, files[fn].chunks) })
90	    })
91	    chain.then(function() {
92	      _log('落盘完成: internal://files/datasets/' + ds + '/', 'success')
93	      var DatasetManager = require('./DatasetManager.js')
94	      var dsObj = DatasetManager.registerDynamicDataset({ dirName: ds, name: name })
95	      // 立刻进加载页：只给这个文件建缓存（loading 页 source=bt 单集模式）
96	      var router = require('@system.router')
97	      router.replace({ uri: '/pages/loading', params: { source: 'bt', dsDir: dsObj.dirName, dsId: String(dsObj.id) } })
98	    }).catch(function(e) {
99	      _log('落盘失败: ' + (e && e.message), 'error')
100	    })
101	  }
102	}
103	
104	// 应用级监听（app.ux onCreate 调一次；重复调用幂等）
105	// ⚠️ 包装链（审查修复）：AssistantEngine 也在这条通道上设 conn.onmessage（语音/AI 真链路），
106	// 直接赋值会互相覆盖（后设者赢，另一模块静默失效）。此处保留原 handler 并转发，
107	// 无论设置顺序如何，两个模块都能收到消息。
108	function initBtReceiver() {
109	  if (registered) return false
110	  try {
111	    var interconnect = require('@system.interconnect')
112	    var conn = interconnect.instance()
113	    var prevHandler = conn.onmessage
114	    conn.onmessage = function(data) {
115	      try { handleMessage(data) } catch (e) { _log('消息处理异常: ' + (e && e.message), 'error') }
116	      // 转发给此前的监听者（如 AssistantEngine 的语音/AI 应答处理）
117	      if (typeof prevHandler === 'function') {
118	        try { prevHandler(data) } catch (e) {}
119	      }
120	    }
121	    registered = true
122	    _log('蓝牙资料接收器已就绪（应用级全局监听）', 'success')
123	    return true
124	  } catch (e) {
125	    _log('interconnect 不可用，接收器未启动（模拟器/无蓝牙环境自动静默）', 'warn')
126	    return false
127	  }
128	}
129	
130	module.exports = { initBtReceiver: initBtReceiver, handleMessage: handleMessage, baseDir: baseDir }
